default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\NTDS\Parameters' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('LdapEnforceChannelBinding', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]2)) {
    Write-Output 'Mismatch: HKLM:\SYSTEM\CurrentControlSet\Services\NTDS\Parameters [LdapEnforceChannelBinding]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\NTDS\Parameters')) {
    New-Item -Path 'HKLM:\SYSTEM\CurrentControlSet\Services\NTDS\Parameters' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SYSTEM\CurrentControlSet\Services\NTDS\Parameters' -Name 'LdapEnforceChannelBinding' -Value 2 -PropertyType DWord -Force | Out-Null
exit 0
